"""Self-contained visual evidence and a concrete, untrained RL design."""
from pathlib import Path
import base64,copy,json,html
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from jump_monitor_data import ROOT,read,atomic,lines
from export_jump_monitor_motion import export
from jump_effort_control import effort_curve,EFFORT_STEMS
from effort_launch_objective import INITIAL_CONTACT_ENVELOPE

R=ROOT/'results/controlled_broad_jump/effort_launch_seed_v2'
OUT=ROOT/'deliverables/standing_long_jump_effort_seed'
LABELS={'hip_flexion':'Hip','knee_angle':'Knee','ankle_angle':'Ankle','flex_extension':'Trunk','shoulder_elv':'Shoulder'}
MEANINGS={'ready_s':'준비 시간','crouch_s':'반동 하강 시간','prepush_lean_s':'밀기 전 전경 유지','push_s':'밀기 시간','ready_shoulder':'팔 준비 각도','shoulder_bottom':'팔 뒤흔들기 각도','shoulder_top':'팔 전방 스윙 각도','elbow':'팔꿈치 굽힘','hip_bottom':'반동 고관절 굽힘','knee_bottom':'반동 무릎 굽힘','ankle_bottom':'반동 발목 각도','trunk_bottom':'반동 체간 굽힘','hip_top':'고관절 신전 목표','knee_top':'무릎 신전 목표','ankle_top':'발목 밀기 목표','trunk_top':'체간 신전 목표','hip_delay':'고관절 신전 시작 시점','knee_delay':'무릎 신전 시작 시점','ankle_delay':'발목 밀기 시작 시점','arm_delay_s':'팔 스윙 시작 시점','hip_extension_duration_fraction':'고관절 신전 소요 시간','knee_extension_duration_fraction':'무릎 신전 소요 시간','lean_m':'전방 균형 목표','pitch_bottom':'반동 골반 기울기 목표','pitch_top':'밀기 골반 기울기 목표','flight_transition_s':'공중 자세 전환 시간','flight_ankle':'공중 발목 각도','flight_trunk':'공중 체간 굽힘','prepare_transition_s':'접촉 자세 전환 시간','prepare_landing_s':'접촉 준비 시작 선행 시간','prepare_hip':'접촉 전 고관절 굽힘','prepare_knee':'접촉 전 무릎 굽힘','prepare_shoulder':'접촉 전 팔 각도','prepare_trunk':'접촉 전 체간 각도','flight_hip':'공중 고관절 굽힘','flight_knee':'공중 무릎 굽힘','flight_shoulder':'공중 팔 각도'}

def image_uri(file):return 'data:image/png;base64,'+base64.b64encode(file.read_bytes()).decode()
def setup():
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'figure.facecolor':'#0c141d','axes.facecolor':'#0c141d','text.color':'#e8f0f6','axes.labelcolor':'#a5b9c9','xtick.color':'#a5b9c9','ytick.color':'#a5b9c9','axes.edgecolor':'#30465a','grid.color':'#30465a'})

def main():
    summary=read(R/'summary.json');assert summary is not None,'Initialization/sensitivity must finish first.'
    initial=read(R/'initial_solution.json');design=read(R/'policy_design.json');sensitivity=read(R/'sensitivity.json');search=read(R/'search_definition.json');policy_init=read(OUT/'policy_initialization.json');assert policy_init is not None,'Initialize and test the new native policy first.'
    OUT.mkdir(parents=True,exist_ok=True);p=initial['parameters'];source=Path(initial['cases'][-1]['folder']);report=read(source/'control_summary.json');z=np.load(source/'control_motion.npz');baseline_folder=ROOT/'results/controlled_broad_jump/overnight_review_2026_11_25/best_500us';old=read(baseline_folder/'control_summary.json');oldz=np.load(baseline_folder/'control_motion.npz');setup()
    recovery=read(R/'recovery_review.json')
    for case in initial['cases']:case.update(recovery_evaluated=False,current_controller_recovery_stable=None)
    summary['initial_solution']=initial
    atomic(R/'initial_solution.json',initial);atomic(R/'summary.json',summary)
    colors=['#73d9bd','#81b4ea','#f0b07b','#c0a4ea','#e9d77c']
    fig,axes=plt.subplots(2,3,figsize=(11,6),sharex=True,sharey=True);u=np.linspace(0,1,300)
    push_start=p['ready_s']+p['crouch_s']+p.get('prepush_lean_s',0.);release_phase=(report['takeoff_s']-push_start)/p['push_s']
    for ax,stem,color in zip(axes.flat,EFFORT_STEMS,colors):
        values=p['propulsion_effort_knots_fraction'][stem];ax.plot(u,[100*effort_curve(x,values)for x in u],c=color,lw=2);ax.scatter([.25,.5,.75],100*np.array(values),s=25,c=color);ax.axhline(0,c='#52687c',lw=.8);ax.axvline(release_phase,c='#a5b9c9',lw=1,ls=':');ax.axvspan(min(release_phase,1),1,color='#52687c',alpha=.15);ax.set(title=LABELS[stem],xlabel='Prescribed push phase',ylabel='Command / fixed torque cap (%)');ax.grid(alpha=.25)
    axes.flat[-1].axis('off');axes.flat[-1].text(.05,.82,'15 effort controls\n5 paired joint channels\n3 smooth interior knots\n\nAdded to the same PD controller\nNet torque ceilings stay fixed\nNo root force or injected GRF',transform=axes.flat[-1].transAxes,color='#a5b9c9',va='top',linespacing=1.7)
    fig.suptitle('New input: timing and magnitude of internal joint effort',fontsize=14);fig.tight_layout();fig.savefig(OUT/'effort_curves.png',dpi=150);plt.close(fig)
    fig,axes=plt.subplots(1,2,figsize=(11,4.2))
    for rep,arr,color,label in [(old,oldz,'#81b4ea','Previous pose-only candidate'),(report,z,'#73d9bd','New force + posture seed')]:
        start=rep['parameters']['ready_s']+rep['parameters']['crouch_s']+rep['parameters'].get('prepush_lean_s',0.);time=arr['physics_times_s'];mask=(time>=start-.1)&(time<=rep['takeoff_s']);axes[0].plot(time[mask]-start,arr['physics_force_world_N'][mask,2]/(87*9.80665),c=color,label=label);axes[1].plot(time[mask]-start,-arr['physics_force_world_N'][mask,1]/(87*9.80665),c=color,label=label)
    for ax,title in zip(axes,['Vertical GRF','Forward GRF']):ax.set(title=title,xlabel='Time from push onset (s)',ylabel='Native contact force (BW)');ax.grid(alpha=.25);ax.spines[['top','right']].set_visible(False)
    axes[0].legend(fontsize=8,frameon=False);fig.tight_layout();fig.savefig(OUT/'ground_reaction.png',dpi=150);plt.close(fig)
    def components(rep,arr):
        toe_y=float(arr['contact_positions_m'][0,:,1].min());offset=-rep['takeoff_COM_m'][1]+toe_y;flight=rep['flight_COM_distance_m'];reach=rep['first_contact_heel_distance_m']-offset-flight
        return [offset,flight,reach]
    before=components(old,oldz);after=components(report,z);fig,ax=plt.subplots(figsize=(10,3.5));left=np.zeros(2)
    for j,(name,color)in enumerate(zip(['Takeoff COM offset','Airborne COM travel','Heel reach about landing COM'],['#81b4ea','#73d9bd','#f0b07b'])):
        values=np.array([before[j],after[j]]);ax.barh([1,0],values,left=left,height=.45,color=color,label=name)
        for y,value,x in zip([1,0],values,left):ax.text(x+value/2,y,f'{value:.2f}',ha='center',va='center',color='#10202b',fontsize=11)
        left+=values
    ax.set(yticks=[1,0],yticklabels=['Previous candidate','New initial solution'],xlabel='Heel projection at first foot contact (m)');ax.legend(loc='upper center',bbox_to_anchor=(.5,1.22),ncol=3,frameon=False,fontsize=8);ax.spines[['top','right']].set_visible(False);fig.tight_layout();fig.savefig(OUT/'distance_components.png',dpi=150);plt.close(fig)
    ranked=design['major_posture_variables'];fig,ax=plt.subplots(figsize=(10,5.6));names=[r['key']for r in ranked];values=[r['local_sensitivity_m_per_normalized_action']*.20*100 for r in ranked];ax.barh(np.arange(len(names)),values,color='#73d9bd');ax.set(yticks=np.arange(len(names)),yticklabels=names,xlabel='Local distance response for a 0.20 normalized change (cm)',title='Posture / timing priorities near this seed');ax.invert_yaxis();ax.grid(axis='x',alpha=.25);ax.spines[['top','right']].set_visible(False);fig.tight_layout();fig.savefig(OUT/'posture_priorities.png',dpi=150);plt.close(fig)
    baseline_motion=export(baseline_folder,target=OUT/'baseline_motion.json',label='Pose-only candidate');seed_motion=export(source,target=OUT/'seed_motion.json',label='Force + posture seed')
    for m,arr in [(baseline_motion,oldz),(seed_motion,z)]:
        m['initial_toe_y_m']=float(arr['contact_positions_m'][0,:,1].min());keep=[i for i,t in enumerate(m['t'])if t<=m['touchdown_s']+.008]
        for key in ['t','xyz','com','grf','phase','velocity']:m[key]=[m[key][i]for i in keep]
    def fixed_height_COM_travel(rep,height=.75):
        vx=-rep['takeoff_velocity_m_s'][1];vz=rep['takeoff_velocity_m_s'][2];h=rep['takeoff_COM_m'][2];return float(vx*(vz+np.sqrt(vz*vz+2*9.80665*(h-height)))/9.80665)
    launch_before=fixed_height_COM_travel(old);launch_after=fixed_height_COM_travel(report)
    atomic(OUT/'force_seed_summary.json',dict(initialization=summary,refinement=initial,recovery_review=recovery,policy_initialization=policy_init,contact_envelope=INITIAL_CONTACT_ENVELOPE,major_posture_variables=ranked,baseline_first_contact_distance_m=old['first_contact_heel_distance_m'],new_first_contact_distance_m=report['first_contact_heel_distance_m'],distance_decomposition_m=dict(baseline=before,new_seed=after),fixed_reference_COM_height_m=.75,ballistic_COM_travel_to_fixed_height_m=dict(baseline=launch_before,new_seed=launch_after),scope='Initial solution + local variable selection + untrained RL design. First-contact projection, not supported/official distance; no individual muscle tensions.'))
    refrows=''.join(f"<tr><td>{r['dt_s']*1000:.3f} ms</td><td>{r['heel_projection_at_first_foot_contact_m']:.3f} m</td><td>{r['contact_COM_height_m']:.3f} m</td><td>{'Passed'if r['optimization_domain_eligible']else'Outside domain'}</td></tr>"for r in initial['cases'])
    varrows=''
    for i,item in enumerate(ranked):
        unit=item['unit'];c=item['center'];lo=item['minimum'];hi=item['maximum'];value=f'{np.degrees(c):.1f}°'if unit=='rad'else f'{c:.3f} {unit}';bounds=f'{np.degrees(lo):.1f}–{np.degrees(hi):.1f}°'if unit=='rad'else f'{lo:.3f}–{hi:.3f} {unit}';varrows+=f"<tr><td>{i+1}</td><td>{MEANINGS.get(item['key'],item['key'])}<br><small>{html.escape(item['key'])}</small></td><td>{value}</td><td>{bounds}</td><td>{'paired'if item['paired_central_difference']else'constraint-sensitive'}</td></tr>"
    values=dict(distance=f"{report['first_contact_heel_distance_m']:.3f}",spread=f"{100*initial['distance_relative_spread']:.2f}",vx=f"{-report['takeoff_velocity_m_s'][1]:.2f}",vz=f"{report['takeoff_velocity_m_s'][2]:.2f}",trials=str(summary['search_trials']),refrows=refrows,varrows=varrows)
    page=PAGE
    for key,value in values.items():page=page.replace('__'+key.upper()+'__',value)
    for key,file in [('EFFORT','effort_curves.png'),('GROUND','ground_reaction.png'),('COMPONENTS','distance_components.png'),('PRIORITIES','posture_priorities.png')]:page=page.replace('__'+key+'__',image_uri(OUT/file))
    if recovery:
        message='기존 제어기로 회복 성공'if recovery['recovery_stable']else'기존 강체 발 제어기로는 회복하지 못함'
        page=page.replace('이후 넘어짐을 도약 점수와 합치지 않습니다.',f'별도의 0.25ms 회복 재생: {message}. 첫 접촉 거리 재현 오차는 {recovery["first_contact_replay_error_m"]:.2e}m이며, 회복 결과를 도약 점수와 합치지 않습니다.')
        if not recovery['recovery_stable']:
            page=page.replace('<h1>힘·자세·타이밍을 함께 조절하는 초기해</h1>','<h1>힘·자세·타이밍 탐색 후보</h1><p class="callout"><b>현재 후보는 안정 착지에 실패했습니다.</b> 첫 접촉 후 약0.1초 이내 현재 모델의 회복 실패 판정이 납니다. 정지 화면은 버틴 결과가 아닙니다. 약2.88m는 접촉거리 탐색 후보이며, 완성 점프의 안정 초기해나 최선해로 채택하지 않습니다. <a href="/video.mp4">이전의 약2.0m 안정 착지 기준 영상</a></p>')
            page=page.replace('새 초기해 / 첫 접촉 거리','탐색 후보 / 첫 접촉 거리').replace('초기해 확보 → 주요 변수 선정 → 학습 모델 초기화·구상','도약부 후보 탐색 → 주요 변수 선정 → 학습 전 모델 구성. 완성 동작의 초기해는 회복 검증이 추가로 필요')
    page=page.replace('발을 더 앞으로 뻗은 효과와 추진으로 COM이 더 멀리 이동한 효과를 분리해서 봅니다.',f'발을 더 앞으로 뻗은 효과와 COM 이동을 분리해서 봅니다. COM 이동량에는 이륙 속도뿐 아니라 접촉 높이의 차이도 들어갑니다. 접촉 COM 높이를 두 경우 모두 0.75m로 맞춘 탄도 기준의 수평 COM 이동은 {launch_before:.2f}m → {launch_after:.2f}m입니다. 이 값은 뒤꿈치 기준 점프 거리와 다릅니다.')
    page=page.replace('각 곡선은 밀기 시작과 끝에서 0이 되며 부드럽게 연결됩니다.','각 명령 곡선은 예정된 밀기 구간의 양 끝에서 0이 되도록 부드럽게 연결됩니다. 실제로는 지면을 밀고 있는 동안에만 추가 토크를 적용하며, 네이티브 이륙 시점에서 추가 출력을 끕니다. 그림의 점선은 실제 이륙 시점이며, 음영 구간의 명령은 적용되지 않습니다.')
    page=page.replace('if(t>=m.touchdown_s)', 'if(t>=m.touchdown_s-.001)')
    anatomy=ROOT/'deliverables/controlled_jump_pilot/effort_seed_anatomy_v1'
    if(anatomy/'fixed_side_metrics.json').exists():
        block='''<section class="panel"><h2>기존 근육 해부 모형으로 렌더링한 새 초기해</h2><video id="anatomyVideo" controls playsinline style="display:block;max-height:85vh;max-width:100%;margin:auto"></video><p>같은 계산 좌표를 기존 3D 해부 모형에 적용했습니다. 강체 분절·관절·질량·관성·발 접촉으로 운동을 계산하고, 표면 메시가 그 운동을 따라갑니다. 회색은 해부 형상 표시이며 근육 장력이나 활성률 색상이 아닙니다. 첫 접촉에서 화면을 잠시 멈추며, 이후 회복을 계산한 영상은 아닙니다.</p></section>'''
        page=page.replace('<section class="panel"><h2>실제 계산된 동작 / 같은 축척의 고정 측면</h2>',block+'<section class="panel"><h2>계산 좌표의 간단한 검토 화면</h2>')
        page=page.replace('</script>','''const anatomyVideo=document.getElementById('anatomyVideo');if(anatomyVideo){anatomyVideo.src=location.protocol==='file:'?'../controlled_jump_pilot/effort_seed_anatomy_v1/fixed_side_multiview_review.mp4':'/effort_anatomy.mp4';anatomyVideo.poster=location.protocol==='file:'?'../controlled_jump_pilot/effort_seed_anatomy_v1/fixed_side_cover.png':'/effort_anatomy_cover.png';}</script>''')
    page=page.replace('__MOTIONS__',json.dumps([baseline_motion,seed_motion],ensure_ascii=False));(OUT/'index.html').write_text(page,encoding='utf-8');print('EFFORT_SEED_PACKAGE_READY',OUT/'index.html',flush=True)

PAGE='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Force + posture / Jump initial solution</title><style>*{box-sizing:border-box}:root{color-scheme:dark}body{margin:0;background:#0c141d;color:#e8f0f6;font:15px/1.65 system-ui,sans-serif}main{max-width:1220px;margin:auto;padding:32px 24px}h1{font-size:30px;line-height:1.35;font-weight:550}h2{font-size:20px;font-weight:550;margin:0 0 15px}p{margin:12px 0}.tag{font-size:11px;letter-spacing:2px;color:#73d9bd}.muted,small{color:#a5b9c9}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}.card,.panel{background:#132130;border:1px solid #2a4052;border-radius:10px;padding:22px}.panel{margin:18px 0}.value{font-size:30px;color:#73d9bd;margin:8px 0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}canvas{display:block;width:100%;height:340px;background:#0b1723;border-radius:7px}.controls{display:flex;align-items:center;gap:12px;margin:15px 0}button,select{padding:7px 13px;background:#20364a;border:1px solid #3e5b72;border-radius:5px;color:#e8f0f6}input{flex:1;accent-color:#73d9bd}img{display:block;width:100%;border-radius:6px;margin:18px 0}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:10px;border-bottom:1px solid #2a4052}th{color:#a5b9c9;font-weight:450}.scroll{overflow:auto}.architecture{display:flex;justify-content:center;align-items:center;gap:15px;padding:20px 0}.layer{text-align:center;border:1px solid #3c5d73;border-radius:7px;padding:12px 18px}.layer strong{font-size:24px;display:block}.arrow{color:#73d9bd}.note{font-size:13px;color:#a5b9c9}.callout{border-left:3px solid #f0b07b;padding-left:17px}a{color:#73d9bd}code{color:#f0b07b}li{margin:8px 0}@media(max-width:800px){.pair{grid-template-columns:1fr}.grid{grid-template-columns:1fr 1fr}.architecture{gap:6px}.layer{padding:8px}main{padding:24px 15px}}
</style></head><body><main><div class="tag">BIOMECHANICS / FORCE + POSTURE / INITIAL SOLUTION</div><h1>힘·자세·타이밍을 함께 조절하는 초기해</h1><p>기존 동작에 15개의 매끄러운 내부 관절 토크 입력을 연결하고, 접촉 전 자세·타이밍 37개와 함께 탐색했습니다. 실제 접촉에서 지면반력이 발생하고, 그 결과로 이륙과 공중 운동이 정해집니다.</p><p class="callout"><b>이 자료는 첫 접촉까지의 초기값과 강화학습 구성안입니다.</b> 거리는 첫 발 접촉 순간 뒤꿈치 위치입니다. 공식 기록·착지 후 회복 성공·사람의 최대 점프 거리를 뜻하지 않습니다. 힘 입력도 개별 근육 장력이 아닌, 현재 모델의 등가 관절 토크입니다.</p><div class="grid"><div class="card"><small>새 초기해 / 첫 접촉 거리</small><div class="value">__DISTANCE__ m</div><small>세 시간 간격에서 재계산</small></div><div class="card"><small>재계산 거리 차이</small><div class="value">__SPREAD__%</div><small>0.5 / 0.25 / 0.125 ms</small></div><div class="card"><small>이륙 수평 / 수직 속도</small><div class="value">__VX__ / __VZ__</div><small>m/s · 입력값이 아닌 계산 결과</small></div><div class="card"><small>새 RL 학습 횟수</small><div class="value">0</div><small>초기 모델 생성·영입력 재생 검사 완료</small></div></div>
<section class="panel"><h2>실제 계산된 동작 / 같은 축척의 고정 측면</h2><div class="pair"><div><b>Previous pose-only candidate</b><canvas id="c0"></canvas><small id="cap0"></small></div><div><b>New force + posture seed</b><canvas id="c1"></canvas><small id="cap1"></small></div></div><div class="controls"><button id="play">Pause</button><select id="speed"><option value="1">1×</option><option value=".5" selected>0.5×</option></select><input id="scrub" type="range" min="0" max="1000" value="0"><span id="stamp"></span></div><p class="note">첫 접촉에서 재생을 멈춥니다. 이후 넘어짐을 도약 점수와 합치지 않습니다. 가시화는 계산된 분절 위치이며, 주황색은 질량중심입니다.</p></section>
<section class="panel"><h2>어떤 힘을 조절하는가?</h2><p>고관절·무릎·발목·체간·어깨에 초반·중반·후반 출력값을 하나씩 둡니다. 각 곡선은 밀기 시작과 끝에서 0이 되며 부드럽게 연결됩니다. 좌우는 동일한 비율을 사용하고, 고정된 각 관절 토크 상한으로 환산합니다.</p><p><code>net torque = posture feedback + scheduled effort + velocity feedback</code></p><p>총 순 토크는 기존과 동일한 상한 안에서 계산됩니다. 루트 추진력이나 임의의 지면반력을 더하지 않습니다. 이 입력은 <b>등가 관절 토크</b>이므로, 개별 근육의 뉴턴 단위 장력이나 실측 근력이라고 해석하지 않습니다.</p><img src="__EFFORT__" alt="Internal equivalent effort curves"><img src="__GROUND__" alt="Native ground reaction outputs"></section>
<section class="panel"><h2>거리 변화는 어디에서 왔나?</h2><img src="__COMPONENTS__" alt="Decomposition of first contact distance"><p class="note">총 거리를 이륙 순간 COM 위치, 공중 COM 이동, 착지 순간 COM에 대한 뒤꿈치 위치로 나눴습니다. 발을 더 앞으로 뻗은 효과와 추진으로 COM이 더 멀리 이동한 효과를 분리해서 봅니다.</p><table><thead><tr><th>시간 간격</th><th>첫 접촉 거리</th><th>접촉 시 COM 높이</th><th>도약·초기 자세 범위</th></tr></thead><tbody>__REFROWS__</tbody></table><p class="note">초기해가 지나치게 낮은 몸으로 발만 뻗는 방향으로 치우치지 않도록, 접촉 COM 높이 ≥0.55m, 머리·체간·골반의 최소 높이 여유 proxy ≥0.35m, 체간 기울기 절댓값 ≤1.10rad를 사용했습니다. 이는 <b>보수적인 초기 탐색 범위</b>이며 보편적인 사람의 한계나 착지 가능성의 증명이 아닙니다.</p></section>
<section class="panel"><h2>주요 자세 변수 선정</h2><p>새 초기해 주변에서 52개 입력을 각각 양·음 방향으로 바꾼 <b>104회 국소 비교</b>를 수행했습니다. 아래 10개는 현재 정한 변화 폭에서 거리 반응이 컸던 자세·타이밍 변수입니다.</p><img src="__PRIORITIES__" alt="Local posture sensitivity"><div class="scroll"><table><thead><tr><th>순위</th><th>변수</th><th>초기값</th><th>RL 탐색 범위</th><th>국소 비교</th></tr></thead><tbody>__VARROWS__</tbody></table></div><p class="note">중요도는 이 초기값과 변화 폭에 대한 국소 결과입니다. 제약 경계에 민감한 경우도 별도로 표시했습니다. 주요 변수를 선정해도 나머지를 고정하지 않으며, 접촉 이후에만 작용하는 회복 변수 6개만 이번 도약 정책에서 분리했습니다.</p></section>
<section class="panel"><h2>강화학습 구성안과 초기 모델</h2><div class="architecture"><div class="layer"><strong>7</strong><small>조건</small></div><span class="arrow">→</span><div class="layer"><strong>64</strong><small>Tanh</small></div><span class="arrow">→</span><div class="layer"><strong>64</strong><small>Tanh</small></div><span class="arrow">→</span><div class="layer"><strong>52</strong><small>37 자세·타이밍 + 15 힘</small></div></div><ul><li><b>정책:</b> Gaussian actor와 별도 value critic. 한 번의 출력으로 한 점프의 변수·힘 곡선을 정하는 파라미터 정책입니다. 매 프레임 반사 제어를 학습하는 정책은 아닙니다.</li><li><b>초기값:</b> 출력 평균 0이 새 초기해를 정확히 재현합니다. 52개 출력과 모든 표준편차를 학습 가능하게 초기화했습니다.</li><li><b>보상:</b> 접촉 전 역학과 명시한 초기 자세 범위가 유효하면, 초기해 대비 첫 접촉 거리의 증가량을 보상합니다. 회복 실패를 이유로 이 보상을 0으로 만들지 않습니다.</li><li><b>고정 조건:</b> 신체 질량·관성, 토크 상한, 피드백 이득, 중력·마찰·접촉 조건. 신경 피로·대사·개별 근육의 힘 분배는 이번 초기 모델에 포함하지 않습니다.</li><li><b>학습 제안:</b> PPO-Clip, 네이티브 물리 worker 3개, worker당 32회 rollout, batch 32, epoch 4, learning rate 1e−5, KL 목표 0.01. 주요 자세와 힘의 초기 탐색 표준편차 0.04, 나머지 자세 0.02에서 시작합니다.</li><li><b>평가:</b> 평균 정책과 최고 표본을 분리하고 0.5/0.25/0.125ms에서 재계산합니다. 접촉 전 성능과 착지 시 속도·각운동량·회복 상태를 별도 기록합니다.</li></ul><p>새 PPO 학습은 아직 시작하지 않았습니다. 요청한 범위인 <b>초기해 확보 → 주요 변수 선정 → 학습 모델 초기화·구상</b>까지 준비했습니다.</p><p><a href="policy_initialization.json">초기화·물리 재생 검사</a> · <a href="effort_launch_policy_initial.zip">학습 전 모델</a> · <a href="force_seed_summary.json">전체 근거 데이터</a></p></section>
<p class="note">모델: 178cm / 87kg · 강체 발·시상면 동작 · RK4 · 네이티브 접촉 · 개별 발가락·회복 스텝 없음. 초기값 탐색은 CEM __TRIALS__회이며 강화학습 결과로 표시하지 않습니다. 기존 무조건 첫 접촉 거리 탐색은 진단 자료로 보존하고, 새 초기 자세 범위를 적용한 v2를 사용했습니다.</p></main><script>
const M=__MOTIONS__,E=id=>document.getElementById(id);let clock=0,last=performance.now(),playing=true;const duration=Math.max(...M.map(m=>m.t.at(-1)));E('play').onclick=()=>{playing=!playing;E('play').textContent=playing?'Pause':'Play'};E('scrub').oninput=()=>{playing=false;E('play').textContent='Play';clock=+E('scrub').value/1000*duration};function draw(k,t){const m=M[k],el=E('c'+k),r=el.getBoundingClientRect(),d=devicePixelRatio||1;el.width=r.width*d;el.height=r.height*d;const c=el.getContext('2d');c.scale(d,d);const w=r.width,h=r.height,scale=Math.min((w-40)/4.1,(h-50)/2.05),gy=h-30,P=v=>[20+(-v[1]+m.initial_toe_y_m+.4)*scale,gy-v[2]*scale];let i=m.t.findIndex(x=>x>=t);if(i<0)i=m.t.length-1;c.strokeStyle='#30465a';c.font='10px system-ui';c.fillStyle='#a5b9c9';c.textAlign='center';c.beginPath();c.moveTo(8,gy);c.lineTo(w-8,gy);c.stroke();for(let x=0;x<=3.5;x+=.5){const p=P([0,m.initial_toe_y_m-x,0]);c.fillText(x.toFixed(1),p[0],gy+18)}if(t>=m.touchdown_s){const path=m.com.filter((p,j)=>m.t[j]>=m.takeoff_s&&m.t[j]<=m.touchdown_s);c.strokeStyle='#f0b07b';c.setLineDash([3,3]);c.beginPath();path.forEach((p,j)=>j?c.lineTo(...P(p)):c.moveTo(...P(p)));c.stroke();c.setLineDash([])}const xyz=m.xyz[i];for(let j=0;j<xyz.length;j++){if(m.parents[j]<0)continue;c.strokeStyle=m.names[j].endsWith('_l')?'#5d7f99':'#c5d8e3';c.lineWidth=m.names[j]==='torso'?13:m.names[j].includes('femur')?8:5;c.lineCap='round';c.beginPath();c.moveTo(...P(xyz[j]));c.lineTo(...P(xyz[m.parents[j]]));c.stroke()}const head=m.names.indexOf('head');c.fillStyle='#c5d8e3';c.beginPath();c.arc(...P(xyz[head]),.09*scale,0,2*Math.PI);c.fill();c.fillStyle='#f0b07b';c.beginPath();c.arc(...P(m.com[i]),3,0,2*Math.PI);c.fill();c.textAlign='left';c.fillStyle='#a5b9c9';c.fillText(`GRF ${m.grf[i].toFixed(2)} BW`,12,20);E('cap'+k).textContent=`First-contact heel projection ${m.first_heel_m.toFixed(3)} m`;if(t>=m.touchdown_s){c.fillStyle='#73d9bd';c.fillText('FIRST FOOT CONTACT / end of primary episode',12,40)}}function tick(now){const dt=(now-last)/1000;last=now;if(playing)clock=(clock+dt*(+E('speed').value))%(duration+1.0);const t=Math.min(clock,duration);E('stamp').textContent=t.toFixed(2)+' s';E('scrub').value=t/duration*1000;draw(0,t);draw(1,t);requestAnimationFrame(tick)}requestAnimationFrame(tick);
</script></body></html>'''

if __name__=='__main__':main()
